["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"__toString() dùng để làm gì?","answer"=>"Định nghĩa cách một object sẽ được chuyển đổi thành chuỗi khi dùng echo, print hoặc ép kiểu (string).","difficulty"=>"Dễ"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Namespace dùng để làm gì trong OOP?","answer"=>"Giúp tránh xung đột tên class, hàm, hằng số giữa các thư viện khác nhau, đồng thời tổ chức code rõ ràng theo module.","difficulty"=>"Trung bình"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Interface có thể có thuộc tính (property) không?","answer"=>"Không, interface chỉ được phép định nghĩa hằng số và khai báo chữ ký phương thức, không có thuộc tính hay thân hàm cụ thể.","difficulty"=>"Trung bình"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Abstract method là gì?","answer"=>"Là phương thức chỉ được khai báo chữ ký mà không có thân hàm, bắt buộc mọi class con kế thừa phải triển khai lại.","difficulty"=>"Trung bình"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Có thể kế thừa nhiều class trong PHP không?","answer"=>"Không, PHP chỉ hỗ trợ đơn kế thừa (single inheritance); để mở rộng chức năng cần dùng thêm trait hoặc interface.","difficulty"=>"Dễ"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Final class và final method dùng để làm gì?","answer"=>"Từ khóa final ngăn không cho một class bị kế thừa hoặc ngăn một phương thức bị override ở class con.","difficulty"=>"Trung bình"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Constant trong class khai báo thế nào?","answer"=>"Dùng từ khóa const bên trong class, ví dụ const PI = 3.14, và truy cập qua TenClass::PI.","difficulty"=>"Dễ"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Dependency Injection là gì?","answer"=>"Là kỹ thuật truyền các đối tượng phụ thuộc vào một class thông qua constructor hoặc setter, thay vì để class đó tự khởi tạo bên trong.","difficulty"=>"Khó"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Interface segregation là gì?","answer"=>"Là một trong các nguyên tắc SOLID, khuyến khích chia nhỏ interface thành nhiều interface chuyên biệt thay vì một interface lớn đa chức năng.","difficulty"=>"Khó"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Clone object trong PHP thực hiện thế nào?","answer"=>"Dùng từ khóa clone để tạo bản sao của object, có thể tùy chỉnh hành vi sao chép qua magic method __clone().","difficulty"=>"Trung bình"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"instanceof dùng để làm gì?","answer"=>"Dùng để kiểm tra xem một object có phải là thực thể của một class hoặc interface cụ thể hay không.","difficulty"=>"Dễ"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Readonly property trong PHP 8.1 là gì?","answer"=>"Là thuộc tính chỉ được phép gán giá trị đúng một lần duy nhất (thường ngay trong constructor), sau đó không thể thay đổi được nữa.","difficulty"=>"Khó"],
["category"=>"Lập trình hướng đối tượng (OOP)","question"=>"Enum trong PHP 8.1 là gì?","answer"=>"Là kiểu dữ liệu đại diện cho một tập hợp các giá trị cố định, giúp code an toàn kiểu và rõ ràng hơn so với dùng hằng số rời rạc.","difficulty"=>"Trung bình"],

["category"=>"Xử lý lỗi & Exception","question"=>"try-catch-finally hoạt động thế nào?","answer"=>"try chứa đoạn code có thể phát sinh lỗi, catch bắt và xử lý exception tương ứng, finally luôn được thực thi dù có lỗi xảy ra hay không.","difficulty"=>"Dễ"],
["category"=>"Xử lý lỗi & Exception","question"=>"Exception và Error khác nhau gì trong PHP7+?","answer"=>"Cả hai đều implement interface Throwable; Exception thường dùng cho lỗi logic ứng dụng, còn Error dành cho lỗi nghiêm trọng của PHP như TypeError hay DivisionByZeroError.","difficulty"=>"Trung bình"],
["category"=>"Xử lý lỗi & Exception","question"=>"Cách tạo một custom exception?","answer"=>"Tạo một class kế thừa từ Exception (hoặc các lớp con như RuntimeException) và có thể override constructor để thêm dữ liệu riêng.","difficulty"=>"Trung bình"],
["category"=>"Xử lý lỗi & Exception","question"=>"throw dùng để làm gì?","answer"=>"Dùng để ném ra một exception, làm dừng luồng thực thi bình thường và chuyển điều khiển sang khối catch gần nhất phù hợp.","difficulty"=>"Dễ"],
["category"=>"Xử lý lỗi & Exception","question"=>"set_error_handler() dùng để làm gì?","answer"=>"Đăng ký một hàm xử lý lỗi tùy chỉnh để thay thế cơ chế xử lý lỗi mặc định của PHP.","difficulty"=>"Trung bình"],
["category"=>"Xử lý lỗi & Exception","question"=>"Multi-catch (PHP 7.1+) là gì?","answer"=>"Cho phép bắt nhiều loại exception khác nhau trong cùng một khối catch bằng cách phân tách các loại đó bằng dấu gạch đứng (|).","difficulty"=>"Trung bình"],
["category"=>"Xử lý lỗi & Exception","question"=>"finally block có luôn được thực thi không?","answer"=>"Có, khối finally hầu như luôn được thực thi, trừ trường hợp script bị dừng đột ngột bởi exit hoặc lỗi nghiêm trọng làm crash tiến trình.","difficulty"=>"Trung bình"],
["category"=>"Xử lý lỗi & Exception","question"=>"Cách log lỗi trong PHP?","answer"=>"Dùng hàm error_log() có sẵn của PHP, hoặc sử dụng các thư viện log chuyên dụng như Monolog để ghi log có cấu trúc.","difficulty"=>"Trung bình"],

["category"=>"Session & Cookie","question"=>"Session và Cookie khác nhau gì?","answer"=>"Session lưu trữ dữ liệu ở phía server và chỉ gửi ID định danh tới client, còn Cookie lưu trữ trực tiếp dữ liệu ở phía trình duyệt của client.","difficulty"=>"Dễ"],
["category"=>"Session & Cookie","question"=>"session_start() dùng để làm gì?","answer"=>"Khởi tạo một session mới hoặc tiếp tục một session hiện có dựa trên session ID gửi kèm từ client.","difficulty"=>"Dễ"],
["category"=>"Session & Cookie","question"=>"Cách hủy session trong PHP?","answer"=>"Dùng session_unset() để xóa toàn bộ biến session, sau đó gọi session_destroy() để hủy session trên server.","difficulty"=>"Trung bình"],
["category"=>"Session & Cookie","question"=>"setcookie() có những tham số quan trọng nào?","answer"=>"Tên cookie, giá trị, thời gian hết hạn, đường dẫn (path), tên miền (domain), cờ secure và cờ httponly.","difficulty"=>"Trung bình"],
["category"=>"Session & Cookie","question"=>"HttpOnly cookie có tác dụng gì?","answer"=>"Ngăn JavaScript phía client truy cập vào cookie, giúp giảm nguy cơ bị đánh cắp cookie thông qua tấn công XSS.","difficulty"=>"Trung bình"],
["category"=>"Session & Cookie","question"=>"Session fixation là gì và cách phòng chống?","answer"=>"Là kỹ thuật tấn công cố định session ID của nạn nhân từ trước; phòng chống bằng cách gọi session_regenerate_id() ngay sau khi người dùng đăng nhập thành công.","difficulty"=>"Khó"],
["category"=>"Session & Cookie","question"=>"Session timeout được cấu hình thế nào?","answer"=>"Cấu hình qua tham số session.gc_maxlifetime trong php.ini, hoặc tự kiểm tra thời gian hoạt động cuối trong logic của ứng dụng.","difficulty"=>"Trung bình"],

["category"=>"Bảo mật (Security)","question"=>"SQL Injection là gì và cách phòng chống?","answer"=>"Là kỹ thuật chèn mã SQL độc hại thông qua dữ liệu đầu vào; phòng chống hiệu quả nhất bằng Prepared Statement của PDO hoặc MySQLi thay vì nối chuỗi trực tiếp vào câu truy vấn.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"XSS (Cross-site scripting) là gì và cách phòng chống?","answer"=>"Là kỹ thuật chèn mã script độc hại vào trang web để chạy trên trình duyệt nạn nhân; phòng chống bằng cách dùng htmlspecialchars() khi hiển thị dữ liệu do người dùng nhập.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"CSRF là gì và cách phòng chống?","answer"=>"Là kỹ thuật giả mạo yêu cầu từ người dùng đã xác thực để thực hiện hành động ngoài ý muốn; phòng chống bằng cách sinh CSRF token duy nhất cho mỗi form hoặc session và kiểm tra khi xử lý.","difficulty"=>"Khó"],
["category"=>"Bảo mật (Security)","question"=>"Cách mã hóa mật khẩu an toàn trong PHP?","answer"=>"Dùng hàm password_hash() để băm mật khẩu khi lưu trữ và password_verify() để kiểm tra khi người dùng đăng nhập.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"password_hash() dùng thuật toán gì mặc định?","answer"=>"Mặc định sử dụng thuật toán bcrypt (hằng số PASSWORD_DEFAULT), ngoài ra có thể chọn Argon2i hoặc Argon2id.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"Prepared Statement là gì?","answer"=>"Là câu truy vấn SQL được biên dịch trước với các placeholder tham số, giúp tách biệt dữ liệu và câu lệnh, chống lại tấn công SQL Injection hiệu quả.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"File upload cần kiểm tra những gì để đảm bảo an toàn?","answer"=>"Kiểm tra loại file thực tế (MIME type), giới hạn kích thước, đổi tên file ngẫu nhiên, và tránh lưu file thực thi trực tiếp trong thư mục public.","difficulty"=>"Khó"],
["category"=>"Bảo mật (Security)","question"=>"Cách chống tấn công Brute Force khi đăng nhập?","answer"=>"Giới hạn số lần đăng nhập sai cho phép, thêm captcha, khóa tài khoản tạm thời và áp dụng cơ chế rate limiting theo IP.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"CORS là gì?","answer"=>"Là cơ chế (Cross-Origin Resource Sharing) cho phép hoặc kiểm soát các request từ một domain khác truy cập tài nguyên trên server.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"Cách bảo vệ một API endpoint?","answer"=>"Dùng cơ chế xác thực bằng token (JWT, OAuth2), bắt buộc HTTPS, áp dụng rate limiting và luôn validate dữ liệu đầu vào.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"Open redirect vulnerability là gì?","answer"=>"Là lỗ hổng cho phép kẻ tấn công lợi dụng tham số redirect không được kiểm soát để chuyển hướng người dùng đến một URL độc hại.","difficulty"=>"Khó"],
["category"=>"Bảo mật (Security)","question"=>"Cách validate và sanitize input trong PHP?","answer"=>"Dùng hàm filter_var() kết hợp với các bộ lọc như FILTER_VALIDATE_EMAIL để kiểm tra hoặc FILTER_SANITIZE_STRING để làm sạch dữ liệu.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"JWT là gì?","answer"=>"JSON Web Token là một chuẩn token dùng để xác thực và trao đổi thông tin an toàn giữa các bên, gồm ba phần header, payload và signature.","difficulty"=>"Trung bình"],
["category"=>"Bảo mật (Security)","question"=>"Directory traversal là gì?","answer"=>"Là lỗ hổng cho phép kẻ tấn công truy cập các file nằm ngoài thư mục cho phép bằng cách thao túng đường dẫn, ví dụ dùng chuỗi ../.","difficulty"=>"Khó"],
["category"=>"Bảo mật (Security)","question"=>"HTTPS khác HTTP như thế nào và tại sao quan trọng?","answer"=>"HTTPS mã hóa dữ liệu truyền tải giữa client và server bằng SSL/TLS, giúp bảo vệ dữ liệu khỏi bị nghe lén hoặc giả mạo trên đường truyền.","difficulty"=>"Dễ"],

["category"=>"MySQL & PDO","question"=>"PDO là gì?","answer"=>"PHP Data Objects là một lớp giao tiếp cơ sở dữ liệu hướng đối tượng, hỗ trợ nhiều hệ quản trị khác nhau như MySQL, PostgreSQL, SQLite.","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"PDO và MySQLi khác nhau gì?","answer"=>"PDO hỗ trợ nhiều loại cơ sở dữ liệu và có cú pháp named parameter linh hoạt, trong khi MySQLi chỉ hoạt động được với MySQL.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Cách kết nối database bằng PDO?","answer"=>"Khởi tạo đối tượng new PDO với chuỗi DSN, tên đăng nhập và mật khẩu, ví dụ new PDO('mysql:host=localhost;dbname=test', \$user, \$pass).","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"Prepared statement trong PDO thực hiện thế nào?","answer"=>"Gọi \$pdo->prepare() để chuẩn bị câu lệnh với placeholder, sau đó gọi \$stmt->execute() truyền vào mảng tham số thực tế.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"fetch() và fetchAll() khác nhau gì?","answer"=>"fetch() chỉ lấy một dòng kết quả tiếp theo trong tập kết quả, còn fetchAll() lấy toàn bộ các dòng và trả về dưới dạng một mảng.","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"PDO::FETCH_ASSOC dùng để làm gì?","answer"=>"Chỉ định kết quả truy vấn được trả về dưới dạng mảng liên kết với khóa chính là tên cột trong bảng.","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"Transaction trong PDO thực hiện thế nào?","answer"=>"Gọi beginTransaction() để bắt đầu, commit() để lưu các thay đổi, hoặc rollBack() để hủy bỏ nếu có lỗi xảy ra, đảm bảo tính toàn vẹn dữ liệu.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"lastInsertId() dùng để làm gì?","answer"=>"Lấy giá trị ID tự động tăng (auto increment) của bản ghi vừa được chèn (INSERT) gần nhất trong phiên kết nối hiện tại.","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"Index trong MySQL có tác dụng gì?","answer"=>"Tạo cấu trúc tra cứu nhanh trên một hoặc nhiều cột, giúp tăng đáng kể tốc độ các câu truy vấn tìm kiếm và sắp xếp dữ liệu.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"JOIN trong SQL gồm những loại nào?","answer"=>"INNER JOIN, LEFT JOIN, RIGHT JOIN và FULL JOIN (MySQL không hỗ trợ trực tiếp FULL JOIN, cần mô phỏng bằng UNION).","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Sự khác nhau giữa INNER JOIN và LEFT JOIN?","answer"=>"INNER JOIN chỉ lấy các dòng có dữ liệu khớp ở cả hai bảng, còn LEFT JOIN lấy toàn bộ dòng của bảng trái kèm theo dữ liệu khớp (nếu có) từ bảng phải.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Normalization trong database là gì?","answer"=>"Là quá trình tổ chức lại cấu trúc dữ liệu nhằm giảm dư thừa và đảm bảo tính toàn vẹn, thường chia thành các dạng chuẩn như 1NF, 2NF, 3NF.","difficulty"=>"Khó"],
["category"=>"MySQL & PDO","question"=>"Foreign Key dùng để làm gì?","answer"=>"Tạo ràng buộc tham chiếu giữa hai bảng, đảm bảo tính toàn vẹn dữ liệu và ngăn chặn các bản ghi liên kết không hợp lệ.","difficulty"=>"Dễ"],
["category"=>"MySQL & PDO","question"=>"Sự khác nhau giữa VARCHAR và TEXT?","answer"=>"VARCHAR có giới hạn độ dài xác định trước và lưu trực tiếp trong dòng dữ liệu, còn TEXT dùng để lưu dữ liệu văn bản lớn hơn và thường được lưu tách biệt.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Cách tối ưu một truy vấn chậm trong MySQL?","answer"=>"Dùng lệnh EXPLAIN để phân tích kế hoạch thực thi, thêm index phù hợp, tránh dùng SELECT *, và giới hạn lượng dữ liệu trả về bằng LIMIT.","difficulty"=>"Khó"],
["category"=>"MySQL & PDO","question"=>"N+1 query problem là gì?","answer"=>"Là vấn đề hiệu năng khi thực hiện một truy vấn lấy danh sách rồi tiếp tục thực hiện N truy vấn riêng lẻ cho từng phần tử con; khắc phục bằng JOIN hoặc eager loading.","difficulty"=>"Khó"],
["category"=>"MySQL & PDO","question"=>"Stored Procedure là gì?","answer"=>"Là một tập hợp các câu lệnh SQL được biên soạn và lưu sẵn trong cơ sở dữ liệu, có thể được gọi thực thi lại nhiều lần.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Trigger trong MySQL là gì?","answer"=>"Là đoạn code được tự động thực thi khi có sự kiện INSERT, UPDATE hoặc DELETE xảy ra trên một bảng cụ thể.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"ORM là gì? Cho ví dụ trong PHP.","answer"=>"Object-Relational Mapping là kỹ thuật ánh xạ bảng cơ sở dữ liệu thành các object trong code, ví dụ Eloquent trong Laravel hoặc Doctrine.","difficulty"=>"Trung bình"],
["category"=>"MySQL & PDO","question"=>"Migration trong Laravel dùng để làm gì?","answer"=>"Cho phép quản lý và đồng bộ cấu trúc cơ sở dữ liệu bằng code theo từng phiên bản, dễ dàng chia sẻ và triển khai giữa các môi trường.","difficulty"=>"Trung bình"],

["category"=>"Composer & Autoload","question"=>"Composer là gì?","answer"=>"Là công cụ quản lý các thư viện phụ thuộc (dependency) phổ biến nhất cho các dự án PHP.","difficulty"=>"Dễ"],
["category"=>"Composer & Autoload","question"=>"composer.json dùng để làm gì?","answer"=>"Là file khai báo thông tin của dự án và danh sách các package cần được cài đặt.","difficulty"=>"Dễ"],
["category"=>"Composer & Autoload","question"=>"PSR-4 autoloading là gì?","answer"=>"Là chuẩn quy định cách tự động nạp class dựa trên việc ánh xạ namespace tương ứng với cấu trúc thư mục trên đĩa.","difficulty"=>"Trung bình"],
["category"=>"Composer & Autoload","question"=>"composer require dùng để làm gì?","answer"=>"Cài đặt một package mới vào dự án và tự động thêm khai báo của nó vào file composer.json.","difficulty"=>"Dễ"],
["category"=>"Composer & Autoload","question"=>"composer.lock có tác dụng gì?","answer"=>"Ghi lại chính xác phiên bản của tất cả các package đã cài đặt, đảm bảo mọi môi trường cài lại đều nhận đúng phiên bản đồng nhất.","difficulty"=>"Trung bình"],
["category"=>"Composer & Autoload","question"=>"autoload.php do Composer sinh ra dùng để làm gì?","answer"=>"Tự động include các class cần thiết trong dự án mà không cần khai báo require thủ công cho từng file.","difficulty"=>"Dễ"],
["category"=>"Composer & Autoload","question"=>"Semantic Versioning (SemVer) là gì?","answer"=>"Là quy tắc đánh số phiên bản theo dạng MAJOR.MINOR.PATCH, thể hiện mức độ và loại thay đổi so với phiên bản trước.","difficulty"=>"Trung bình"],
["category"=>"Composer & Autoload","question"=>"composer update và composer install khác nhau gì?","answer"=>"composer install cài đặt package đúng theo phiên bản đã ghi trong composer.lock, còn composer update cập nhật package theo composer.json và ghi lại file lock mới.","difficulty"=>"Trung bình"],

["category"=>"Design Patterns","question"=>"Singleton pattern là gì?","answer"=>"Là mẫu thiết kế đảm bảo một class chỉ có duy nhất một instance trong suốt vòng đời ứng dụng và cung cấp một điểm truy cập toàn cục tới nó.","difficulty"=>"Trung bình"],
["category"=>"Design Patterns","question"=>"Factory pattern là gì?","answer"=>"Là mẫu thiết kế cung cấp một phương thức để tạo object mà không cần client phải biết chính xác class cụ thể nào sẽ được khởi tạo.","difficulty"=>"Trung bình"],
["category"=>"Design Patterns","question"=>"Observer pattern là gì?","answer"=>"Cho phép một object (subject) tự động thông báo cho nhiều object khác (observer) mỗi khi trạng thái của nó thay đổi.","difficulty"=>"Trung bình"],
["category"=>"Design Patterns","question"=>"MVC là gì?","answer"=>"Là mô hình kiến trúc phần mềm chia ứng dụng thành ba phần: Model (dữ liệu và nghiệp vụ), View (giao diện hiển thị) và Controller (điều phối logic).","difficulty"=>"Dễ"],
["category"=>"Design Patterns","question"=>"Repository pattern là gì?","answer"=>"Là một lớp trung gian nằm giữa logic nghiệp vụ và tầng truy xuất dữ liệu, giúp tách biệt và dễ dàng thay đổi cách lấy dữ liệu.","difficulty"=>"Trung bình"],
["category"=>"Design Patterns","question"=>"Strategy pattern là gì?","answer"=>"Cho phép định nghĩa một họ các thuật toán, đóng gói riêng từng thuật toán và có thể hoán đổi linh hoạt với nhau tại thời điểm runtime.","difficulty"=>"Khó"],
["category"=>"Design Patterns","question"=>"Dependency Injection Container là gì?","answer"=>"Là một công cụ tự động quản lý việc khởi tạo và tiêm (inject) các dependency cần thiết vào class khi được yêu cầu.","difficulty"=>"Khó"],
["category"=>"Design Patterns","question"=>"Adapter pattern là gì?","answer"=>"Chuyển đổi interface của một class hiện có thành một interface khác phù hợp với những gì client mong muốn sử dụng.","difficulty"=>"Trung bình"],
["category"=>"Design Patterns","question"=>"SOLID là gì?","answer"=>"Là năm nguyên tắc thiết kế hướng đối tượng: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation và Dependency Inversion.","difficulty"=>"Khó"],
["category"=>"Design Patterns","question"=>"Facade pattern là gì?","answer"=>"Cung cấp một giao diện đơn giản, thống nhất để truy cập vào một hệ thống con phức tạp gồm nhiều class bên trong.","difficulty"=>"Trung bình"],

["category"=>"Hiệu năng & Tối ưu","question"=>"OPcache là gì?","answer"=>"Là cơ chế cache mã bytecode đã được biên dịch của PHP, giúp giảm thời gian biên dịch lại script ở mỗi request và tăng tốc độ thực thi.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Cách giảm thời gian tải trang trong ứng dụng PHP?","answer"=>"Áp dụng cache (OPcache, Redis, Memcached), tối ưu truy vấn database, nén tài nguyên tĩnh và áp dụng lazy loading khi phù hợp.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Lazy loading là gì?","answer"=>"Là kỹ thuật chỉ tải dữ liệu hoặc tài nguyên khi thực sự cần dùng đến, giúp giảm tải ban đầu cho ứng dụng.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Eager loading khác lazy loading thế nào?","answer"=>"Eager loading tải trước toàn bộ dữ liệu liên quan cùng một lúc để tránh vấn đề N+1 query, còn lazy loading chỉ tải khi cần đến.","difficulty"=>"Khó"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Cách sử dụng Redis hoặc Memcached trong PHP?","answer"=>"Cài extension redis hoặc memcached tương ứng, sau đó lưu và lấy dữ liệu dạng key-value nhằm giảm số lần truy vấn trực tiếp vào database.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Garbage Collection trong PHP hoạt động thế nào?","answer"=>"PHP tự động giải phóng bộ nhớ của các biến hoặc object không còn được tham chiếu tới trong chương trình.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Cách profiling một ứng dụng PHP?","answer"=>"Sử dụng các công cụ chuyên dụng như Xdebug hoặc Blackfire để phân tích thời gian thực thi và mức sử dụng bộ nhớ của từng đoạn code.","difficulty"=>"Khó"],
["category"=>"Hiệu năng & Tối ưu","question"=>"CDN có lợi ích gì cho ứng dụng PHP?","answer"=>"Giảm tải cho server gốc và tăng tốc độ tải các tài nguyên tĩnh nhờ phân phối nội dung từ máy chủ gần với vị trí người dùng.","difficulty"=>"Dễ"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Queue (hàng đợi) dùng để làm gì trong PHP?","answer"=>"Dùng để xử lý các tác vụ nặng hoặc không yêu cầu thực thi ngay lập tức (gửi email, xử lý ảnh...) một cách bất đồng bộ trong nền.","difficulty"=>"Trung bình"],
["category"=>"Hiệu năng & Tối ưu","question"=>"Load balancing là gì?","answer"=>"Là kỹ thuật phân phối tải các request đến nhiều server khác nhau nhằm tăng khả năng chịu tải và độ sẵn sàng của hệ thống.","difficulty"=>"Trung bình"],

["category"=>"RESTful API","question"=>"RESTful API là gì?","answer"=>"Là kiến trúc thiết kế API sử dụng các phương thức HTTP như GET, POST, PUT, DELETE để thao tác trên các tài nguyên được định danh qua URL.","difficulty"=>"Dễ"],
["category"=>"RESTful API","question"=>"Các HTTP method phổ biến dùng trong REST API?","answer"=>"GET để lấy dữ liệu, POST để tạo mới, PUT hoặc PATCH để cập nhật, DELETE để xóa tài nguyên.","difficulty"=>"Dễ"],
["category"=>"RESTful API","question"=>"Status code 200, 201, 400, 401, 404, 500 có ý nghĩa gì?","answer"=>"200 là thành công, 201 tạo mới thành công, 400 lỗi dữ liệu request, 401 chưa xác thực, 404 không tìm thấy tài nguyên, 500 lỗi phía server.","difficulty"=>"Dễ"],
["category"=>"RESTful API","question"=>"Sự khác nhau giữa PUT và PATCH?","answer"=>"PUT thường dùng để cập nhật toàn bộ tài nguyên, còn PATCH chỉ cập nhật một phần dữ liệu của tài nguyên đó.","difficulty"=>"Trung bình"],
["category"=>"RESTful API","question"=>"Cách versioning cho một API?","answer"=>"Có thể đặt số version trực tiếp trong đường dẫn URL (ví dụ /api/v1/) hoặc truyền thông qua một header riêng của request.","difficulty"=>"Trung bình"],
["category"=>"RESTful API","question"=>"Idempotent trong REST API nghĩa là gì?","answer"=>"Nghĩa là gọi cùng một request nhiều lần vẫn cho ra kết quả giống nhau trên server, ví dụ các phương thức GET, PUT, DELETE đều mang tính idempotent.","difficulty"=>"Khó"],
["category"=>"RESTful API","question"=>"Rate limiting cho API là gì?","answer"=>"Là kỹ thuật giới hạn số lượng request mà một client được phép gửi tới trong một khoảng thời gian nhất định.","difficulty"=>"Trung bình"],
["category"=>"RESTful API","question"=>"Các cách xác thực API phổ biến?","answer"=>"API Key, Basic Authentication, OAuth2, và JWT token là các phương thức xác thực API phổ biến hiện nay.","difficulty"=>"Trung bình"],

["category"=>"Laravel cơ bản","question"=>"Laravel là gì?","answer"=>"Là một framework PHP mã nguồn mở theo mô hình MVC, cung cấp sẵn nhiều công cụ giúp phát triển ứng dụng web nhanh chóng và có cấu trúc rõ ràng.","difficulty"=>"Dễ"],
["category"=>"Laravel cơ bản","question"=>"Eloquent ORM là gì?","answer"=>"Là ORM được tích hợp sẵn trong Laravel, giúp ánh xạ các bảng trong cơ sở dữ liệu thành các model PHP để thao tác dễ dàng hơn.","difficulty"=>"Trung bình"],
["category"=>"Laravel cơ bản","question"=>"Middleware trong Laravel dùng để làm gì?","answer"=>"Dùng để lọc và xử lý HTTP request trước hoặc sau khi nó đi vào controller, ví dụ như kiểm tra xác thực người dùng.","difficulty"=>"Trung bình"],
["category"=>"Laravel cơ bản","question"=>"Route trong Laravel được định nghĩa thế nào?","answer"=>"Được khai báo trong các file routes/web.php hoặc routes/api.php thông qua các phương thức như Route::get(), Route::post().","difficulty"=>"Dễ"],
["category"=>"Laravel cơ bản","question"=>"Blade template là gì?","answer"=>"Là template engine tích hợp sẵn của Laravel, hỗ trợ các cú pháp tiện lợi như @if, @foreach và cơ chế kế thừa layout.","difficulty"=>"Dễ"],
["category"=>"Laravel cơ bản","question"=>"Service Container trong Laravel là gì?","answer"=>"Là một công cụ mạnh mẽ dùng để quản lý việc khởi tạo và binding các class, giúp thực hiện Dependency Injection dễ dàng.","difficulty"=>"Khó"],
["category"=>"Laravel cơ bản","question"=>"Artisan CLI dùng để làm gì?","answer"=>"Là công cụ dòng lệnh của Laravel, dùng để tạo migration, model, controller, chạy tác vụ nền và nhiều lệnh tiện ích khác.","difficulty"=>"Dễ"],
["category"=>"Laravel cơ bản","question"=>"Facade trong Laravel là gì?","answer"=>"Cung cấp một interface tĩnh (static) tiện lợi để truy cập tới các class đã được đăng ký trong service container.","difficulty"=>"Trung bình"],
["category"=>"Laravel cơ bản","question"=>"Queue Job trong Laravel dùng để làm gì?","answer"=>"Cho phép đưa các tác vụ nặng hoặc tốn thời gian vào hàng đợi để xử lý bất đồng bộ trong background, không làm chậm request chính.","difficulty"=>"Trung bình"],
["category"=>"Laravel cơ bản","question"=>"Event và Listener trong Laravel hoạt động thế nào?","answer"=>"Một Event được bắn ra khi có hành động xảy ra trong ứng dụng, và các Listener tương ứng sẽ lắng nghe để thực hiện logic xử lý riêng.","difficulty"=>"Trung bình"],

["category"=>"Regex","question"=>"preg_match() dùng để làm gì?","answer"=>"Kiểm tra xem một chuỗi có khớp với mẫu biểu thức chính quy (regex) cho trước hay không.","difficulty"=>"Trung bình"],
["category"=>"Regex","question"=>"preg_match_all() khác preg_match() thế nào?","answer"=>"preg_match() chỉ tìm và trả về kết quả khớp đầu tiên, còn preg_match_all() tìm tất cả các kết quả khớp trong chuỗi.","difficulty"=>"Trung bình"],
["category"=>"Regex","question"=>"Ký hiệu ^ và \$ trong regex có ý nghĩa gì?","answer"=>"Dấu ^ đánh dấu vị trí bắt đầu chuỗi (hoặc dòng), dấu \$ đánh dấu vị trí kết thúc chuỗi (hoặc dòng).","difficulty"=>"Trung bình"],
["category"=>"Regex","question"=>"Group trong regex (dấu ngoặc đơn) dùng để làm gì?","answer"=>"Dùng để nhóm các phần của một pattern lại với nhau, phục vụ cho việc trích xuất kết quả con hoặc áp dụng lượng từ chung cho cả nhóm.","difficulty"=>"Khó"],
["category"=>"Regex","question"=>"Sự khác nhau giữa * và + trong regex?","answer"=>"Dấu * khớp với 0 lần hoặc nhiều lần xuất hiện, còn dấu + khớp với ít nhất 1 lần hoặc nhiều lần xuất hiện.","difficulty"=>"Trung bình"],

["category"=>"Xử lý File","question"=>"Cách đọc file trong PHP?","answer"=>"Dùng fopen() kết hợp fread() và fclose() để đọc theo luồng, hoặc dùng file_get_contents() để đọc toàn bộ nội dung file một lần.","difficulty"=>"Dễ"],
["category"=>"Xử lý File","question"=>"Cách ghi file trong PHP?","answer"=>"Dùng fopen() với chế độ 'w' hoặc 'a' kết hợp fwrite(), hoặc đơn giản hơn là dùng hàm file_put_contents().","difficulty"=>"Dễ"],
["category"=>"Xử lý File","question"=>"file_exists() dùng để làm gì?","answer"=>"Kiểm tra xem một file hoặc thư mục có tồn tại trên hệ thống hay không trước khi thao tác với nó.","difficulty"=>"Dễ"],
["category"=>"Xử lý File","question"=>"\$_FILES dùng để làm gì?","answer"=>"Là một superglobal chứa toàn bộ thông tin về các file được người dùng upload thông qua một form HTML.","difficulty"=>"Trung bình"],
["category"=>"Xử lý File","question"=>"move_uploaded_file() dùng để làm gì?","answer"=>"Di chuyển một file vừa được upload từ thư mục tạm thời của server sang vị trí lưu trữ đích được chỉ định.","difficulty"=>"Trung bình"],
["category"=>"Xử lý File","question"=>"Cách đọc file CSV trong PHP?","answer"=>"Dùng hàm fgetcsv() để đọc từng dòng của file CSV và tự động chuyển nó thành một mảng các giá trị.","difficulty"=>"Trung bình"],
["category"=>"Xử lý File","question"=>"Cách nén hoặc giải nén file trong PHP?","answer"=>"Sử dụng extension Zip thông qua class ZipArchive để tạo mới hoặc giải nén các file định dạng .zip.","difficulty"=>"Trung bình"],

["category"=>"Vòng lặp & Điều kiện","question"=>"Sự khác nhau giữa while và do-while?","answer"=>"while kiểm tra điều kiện trước rồi mới thực thi vòng lặp, còn do-while luôn thực thi ít nhất một lần rồi mới kiểm tra điều kiện.","difficulty"=>"Dễ"],
["category"=>"Vòng lặp & Điều kiện","question"=>"break và continue khác nhau gì?","answer"=>"break thoát hoàn toàn ra khỏi vòng lặp hiện tại, còn continue chỉ bỏ qua phần còn lại của lần lặp hiện tại và tiếp tục lần lặp kế tiếp.","difficulty"=>"Dễ"],
["category"=>"Vòng lặp & Điều kiện","question"=>"switch-case hoạt động thế nào?","answer"=>"So sánh giá trị của biến với từng case tương ứng, thực thi khối code khớp và cần có break để tránh hiện tượng fall-through sang case tiếp theo.","difficulty"=>"Dễ"],
["category"=>"Vòng lặp & Điều kiện","question"=>"match expression trong PHP 8 khác switch thế nào?","answer"=>"match so sánh chặt kiểu dữ liệu (giống ===), luôn trả về giá trị trực tiếp, không cần break và không xảy ra hiện tượng fall-through.","difficulty"=>"Trung bình"],
["category"=>"Vòng lặp & Điều kiện","question"=>"Toán tử ternary (?:) dùng để làm gì?","answer"=>"Dùng để viết gọn một câu lệnh if-else đơn giản trên một dòng, theo cú pháp điều_kiện ? giá_trị_đúng : giá_trị_sai.","difficulty"=>"Dễ"],

["category"=>"Namespace","question"=>"Namespace trong PHP dùng để làm gì?","answer"=>"Giúp tổ chức code theo module rõ ràng và tránh xung đột tên giữa các class, hàm, hằng số trùng tên trong dự án.","difficulty"=>"Trung bình"],
["category"=>"Namespace","question"=>"use trong namespace dùng để làm gì?","answer"=>"Dùng để import một namespace hoặc class cụ thể, cho phép sử dụng tên ngắn gọn thay vì phải viết đầy đủ đường dẫn namespace mỗi lần.","difficulty"=>"Trung bình"],
["category"=>"Namespace","question"=>"Cách khai báo namespace trong một file PHP?","answer"=>"Dùng cú pháp namespace Ten\\NamespaceCon; đặt ở ngay đầu file, trước mọi đoạn code khác (ngoại trừ khai báo declare nếu có).","difficulty"=>"Trung bình"],

["category"=>"Testing","question"=>"PHPUnit là gì?","answer"=>"Là framework testing phổ biến nhất dành cho PHP, được sử dụng rộng rãi để viết và chạy các unit test.","difficulty"=>"Dễ"],
["category"=>"Testing","question"=>"Unit Test là gì?","answer"=>"Là hình thức kiểm thử một đơn vị code nhỏ nhất (thường là một hàm hoặc phương thức) một cách độc lập với các phần khác của hệ thống.","difficulty"=>"Dễ"],
];
